D={
80305:("Devolução","Devolver: **I'd like to return this. Here's the receipt. Can I get a refund?** **Refund** = reembolso. *Return the tapes.*",[("{{I'd like to return}} this.","Gostaria de devolver isto."),("{{Here's the receipt}}.","Aqui está o recibo."),("{{Can I get a refund}}?","Posso pedir reembolso?"),("Yes, at the counter.","Sim, no balcão.")],"“Reembolso”:",["refund","receipt","counter"],0,"Refund."),
80306:("When did it…?","Quando: **When did it open? — It opened in 1990.** **When + did + sujeito + verbo base**. Resposta no passado.",[("{{When did}} it open?","Quando abriu?"),("It {{opened}} in 1990.","Abriu em 1990."),("{{When did}} he arrive?","Quando ele chegou?"),("He arrived last night.","Ele chegou ontem à noite.")],"Qual está certa?",["When did it opened?","When did it open?","When it did open?"],1,"did + base."),
80307:("Passados irregulares","Alguns verbos **não usam -ed**: *go → went, see → saw, take → took, wear → wore.* Precisam ser memorizados.",[("I {{wore}} flip-flops.","Usei chinelos."),("She {{took}} a towel.","Ela pegou uma toalha."),("We {{saw}} the waves.","Vimos as ondas."),("They went to the beach.","Eles foram à praia.")],"Passado de take:",["taked","took","taken"],1,"Irregular: took."),
80308:("Went, saw, took","**Went** (go), **saw** (see), **took** (take) são irregulares comuns. *I went to Yosemite. I saw a waterfall. I took photos.*",[("I {{went}} to Yosemite.","Fui a Yosemite."),("I {{saw}} a waterfall.","Vi uma cachoeira."),("I {{took}} many photos.","Tirei muitas fotos."),("We camped by the trail.","Acampamos perto da trilha.")],"Passado de see:",["seed","saw","seen"],1,"Irregular: saw."),
910038:("Get on, get off","**Get on** = subir (ônibus/trem). **Get off** = descer. **Get in/out** para carro. *Get on the bus.*",[("{{Get on}} the bus.","Suba no ônibus."),("{{Get off}} at the next stop.","Desça na próxima parada."),("Hold the handrail.","Segure o corrimão."),("Press the stop button.","Aperte o botão de parada.")],"“Descer do ônibus”:",["get off","get out the","go off the"],0,"Get off."),
80309:("Mergulho no passado","Passado irregular: **swim → swam, see → saw, find → found.** *I swam with turtles. I saw a shark.*",[("I {{swam}} with turtles.","Nadei com tartarugas."),("I {{saw}} a shark.","Vi um tubarão."),("We {{found}} a reef.","Encontramos um recife."),("Bubbles came up.","Bolhas subiram.")],"Passado de swim:",["swimmed","swam","swum"],1,"Irregular: swam."),
80311:("Era uma vez","**A long time ago** = há muito tempo. **There was a king.** *Once upon a time* abre histórias. Passado: **was/were**.",[("{{A long time ago}}, there {{was}} a king.","Há muito tempo, havia um rei."),("{{There was}} a dragon.","Havia um dragão."),("{{There were}} many wishes.","Havia muitos desejos."),("{{Once upon a time}}…","Era uma vez…")],"“Havia uma rainha”:",["There was a queen.","There were a queen.","It had queen."],0,"Singular: There was."),
80312:("Sequência","**Then / after that / next** = em seguida. *The goat crossed the bridge. After that, the troll came.* Passado simples.",[("The goat {{crossed}} the bridge.","A cabra atravessou a ponte."),("{{Then}} the troll {{came}}.","Então o troll veio."),("{{After that}}, it ran.","Depois disso, ela correu."),("What happened next?","O que aconteceu depois?")],"“Depois disso”:",["after that","before that","that after"],0,"After that."),
80313:("Verão passado","Lembranças: **last summer** = no verão passado. *Last year, last week.* Sem preposição: **last summer**, não *in last summer*.",[("{{Last summer}} we had a picnic."," No verão passado, fizemos piquenique."),("We {{drank}} lemonade.","Tomamos limonada."),("It {{was}} sunny.","Estava ensolarado."),("What a lovely memory!","Que lembrança bonita!")],"Qual está certa?",["in last summer","last summer","at last summer"],1,"last + período."),
80314:("Was/were","Passado de be: **Was the opera good? — Yes, it was.** Com **you / we / they** usa **were**. *Were you there?*",[("{{Was}} the opera good?","A ópera foi boa?"),("Yes, it {{was}}.","Sim, foi."),("{{Were}} you there?","Você estava lá?"),("No, I {{wasn't}}.","Não, não estava.")],"Complete: “___ they on stage?”",["Was","Were","Did"],1,"They → were."),
80315:("There was, there were","Passado de *there is/are*: **There was a duck. There were two eggs.** Singular **was**, plural **were**.",[("{{There was}} a duck.","Havia um pato."),("{{There were}} two eggs.","Havia dois ovos."),("{{There was}} cheese.","Havia queijo."),("{{There were}} apples.","Havia maçãs.")],"Complete: “___ three carts.”",["There was","There were","There is"],1,"Plural no passado: were."),
80316:("Need to, have to","**Need to / have to** + verbo base = precisar. *I need to pack. She has to bring a passport.* Ele/ela: **has to**.",[("I {{need to}} pack.","Preciso arrumar a mala."),("She {{has to}} bring a passport.","Ela tem que levar passaporte."),("We {{have to}} leave at six.","Temos que sair às seis."),("Don't forget the charger.","Não esqueça o carregador.")],"Complete: “He ___ to go.”",["have","has","haves"],1,"he → has to."),
910039:("Break a leg!","**Break a leg!** = boa sorte (teatro). Não é desejo ruim: é superstição. Responda: **Thanks!** *Opening night.*",[("{{Break a leg}}!","Boa sorte!"),("I'm full of nerves.","Estou cheio de nervosismo."),("{{Thanks}}!","Obrigado!"),("It's opening night.","É a noite de estreia.")],"O que significa break a leg?",["boa sorte","quebre a perna","corra rápido"],0,"Boa sorte."),
80317:("Ordens com please","Ordens educadas: **Put your bag on the belt, please. Show your boarding pass, please.** Verbo + **please**.",[("{{Put}} your bag on the belt, {{please}}.","Ponha sua bolsa na esteira, por favor."),("{{Show}} your boarding pass.","Mostre seu cartão de embarque."),("{{Step}} through the scanner.","Passe pelo scanner."),("Next passenger, please.","Próximo passageiro, por favor.")],"“Mostre o passaporte, por favor”:",["Show your passport, please.","You show passport.","Passport show you."],0,"Imperativo + please."),
80318:("Window or aisle?","Preferência: **I'd like a window seat. I prefer the aisle.** **Prefer** = prefere. *I prefer the aisle.*",[("{{I'd like}} a window seat.","Gostaria de um assento na janela."),("{{I prefer}} the aisle.","Prefiro o corredor."),("The flight is long.","O voo é longo."),("Fasten your seatbelt.","Aperte o cinto.")],"“Prefiro a janela”:",["I prefer the window.","I prefers window.","I like prefer."],0,"I prefer."),
80319:("Is there…? no hotel","Hotel: **Is the minibar free? Is there Wi-Fi? Are there towels?** *Is there…?* (singular) e *Are there…?* (plural).",[("{{Is there}} breakfast?","Tem café da manhã?"),("{{Is the minibar}} free?","O frigobar é grátis?"),("{{Are there}} towels?","Tem toalhas?"),("The lobby is downstairs.","O saguão é no andar de baixo.")],"Complete: “___ any towels?”",["Is there","Are there","There is"],1,"Plural: Are there."),
80320:("What time does it…?","Horário: **What time does it close?** Resposta: **At five.** Com *it*: **does** + verbo sem -s.",[("{{What time does}} it close?","A que horas fecha?"),("It closes {{at five}}.","Fecha às cinco."),("{{What time does}} it open?","A que horas abre?"),("At nine.","Às nove.")],"Complete: “What time ___ the museum open?”",["do","does","is"],1,"museum = it: does."),
80321:("Can you…?","Pedir foto: **Can you take a photo, please?** *Can you stand there?* **Can you** + verbo base.",[("{{Can you}} take a photo, please?","Pode tirar uma foto, por favor?"),("{{Can you}} stand there?","Pode ficar ali?"),("One more!","Mais uma!"),("Thank you!","Obrigado!")],"“Pode tirar uma foto?”",["Can you take a photo?","You can take photo?","Take can you?"],0,"Can you…?"),
80322:("Descrever lugares","Descrição: **The sun is bright. The sea is blue. The lighthouse is tall.** Adjetivo depois de **be**, sem -s.",[("The sun {{is bright}}.","O sol está forte."),("The sea {{is blue}}.","O mar é azul."),("The lighthouse {{is tall}}.","O farol é alto."),("Seagulls are loud.","Gaivotas são barulhentas.")],"Complete: “The sailboats ___ small.”",["is","are","be"],1,"Plural: are."),
80323:("De volta da viagem","Passado simples: **We arrived home. I bought a souvenir. We hugged.** Irregular: **buy → bought**.",[("We {{arrived}} home.","Chegamos em casa."),("I {{bought}} a souvenir.","Comprei uma lembrancinha."),("We {{hugged}}.","Nos abraçamos."),("Welcome back!","Bem-vindo de volta!")],"Passado de buy:",["buyed","bought","boughted"],1,"Irregular: bought."),
80324:("Going to","Planos: **I'm going to book a flight. We're going to stop in Rome.** **be going to** + verbo.",[("I'm {{going to}} book a flight.","Vou reservar um voo."),("We're {{going to}} stop in Rome.","Vamos fazer escala em Roma."),("She's {{going to}} pay online.","Ela vai pagar online."),("The price has a discount.","O preço tem desconto.")],"“Vamos reservar”:",["We're going to book.","We going book.","We go to book."],0,"be going to."),
910040:("Pardon?","Pedir repetição: **Pardon? / Sorry? / Can you say that again?** *Could you speak up?* = fale mais alto.",[("{{Pardon}}?","Como?"),("{{Sorry}}?","Como é?"),("{{Could you speak up}}?","Pode falar mais alto?"),("What do you mean?","O que você quer dizer?")],"“Fale mais alto”:",["Speak up.","Speak over.","Say high."],0,"Speak up."),
80325:("Too + adjetivo","Reclamar: **It's too hot. The room is too small.** **Too** = demais. *Can you fix the fan?*",[("It's {{too hot}}.","Está quente demais."),("The room is {{too small}}.","O quarto é pequeno demais."),("The remote {{doesn't work}}.","O controle não funciona."),("Can you fix it?","Pode consertar?")],"“Quente demais”:",["too hot","very hots","hot too"],0,"Too hot."),
80326:("Let's, follow me","Guia: **Let's go! Follow me! Stay with the group!** *Let's* = vamos. Imperativo para o grupo.",[("{{Let's go}}!","Vamos!"),("{{Follow me}}.","Sigam-me."),("{{Stay}} with the group.","Fiquem com o grupo."),("Use your headphones.","Use os fones.")],"“Siga-me”:",["Follow me.","Me follow.","Following I."],0,"Follow me."),
80327:("Preposições de lugar","Passeio: **on the corner, next to the bank, across the street.** *The bakery is across from the bank.*",[("The bakery is {{on the corner}}.","A padaria fica na esquina."),("The bank is {{next to}} it.","O banco fica ao lado."),("Cross {{at}} the crosswalk.","Atravesse na faixa de pedestres."),("Stop at the traffic light.","Pare no semáforo.")],"“Do outro lado da rua”:",["across the street","over street the","after street"],0,"across."),
80328:("Animais: adjetivos","Animais: **The tiger is strong. Monkeys are funny.** Plural: *monkeys, wolves, lions.* Adjetivo igual no singular e plural.",[("The tiger {{is}} strong.","O tigre é forte."),("Monkeys {{are}} funny.","Macacos são engraçados."),("The snake is long.","A cobra é comprida."),("Lions are big.","Leões são grandes.")],"Complete: “Elephants ___ big.”",["is","are","be"],1,"Plural: are."),
80329:("Aves: presente simples","Aves: **Birds fly. An eagle has big wings.** Fatos usam presente simples. Terceira pessoa: **has**.",[("Birds {{fly}}.","Pássaros voam."),("An eagle {{has}} big wings.","Uma águia tem asas grandes."),("A bird {{builds}} a nest.","Um pássaro faz um ninho."),("The cage is open.","A gaiola está aberta.")],"Complete: “A bird ___ feathers.”",["have","has","haves"],1,"3ª pessoa: has."),
80330:("Na floresta","Natureza: **There is a path. There are mushrooms.** *There is* + singular, *there are* + plural. **Stream** = riacho.",[("{{There is}} a path.","Há uma trilha."),("{{There are}} mushrooms.","Há cogumelos."),("{{There are}} leaves.","Há folhas."),("{{There is}} a stream.","Há um riacho.")],"Complete: “___ many insects.”",["There is","There are","There be"],1,"Plural."),
80331:("It is + clima","Tempo: **It is snowing. It is windy. It is foggy.** Use sempre **it**. *Wear a scarf.*",[("{{It is}} snowing.","Está nevando."),("{{It is}} windy.","Está ventando."),("{{It is}} foggy.","Está com neblina."),("Build a snowman!","Faça um boneco de neve!")],"“Está ventando”:",["It is windy.","He is windy.","Wind is it."],0,"It is."),
80332:("Plurais irregulares","Fazenda: **sheep → sheep, cow → cows, hen → hens, mouse → mice, goose → geese.** Alguns plurais mudam.",[("One {{cow}}, two {{cows}}.","Uma vaca, duas vacas."),("One {{sheep}}, five {{sheep}}.","Uma ovelha, cinco ovelhas."),("One {{mouse}}, two {{mice}}.","Um rato, dois ratos."),("The barn is big.","O celeiro é grande.")],"Plural de mouse:",["mouses","mice","mices"],1,"Irregular: mice."),
910041:("Raining cats and dogs","**It's raining cats and dogs** = chove a cântaros (idioma). Não tem a ver com animais! Normal: **It's raining hard.**",[("{{It's raining cats and dogs}}!","Está chovendo canivetes!"),("It's {{raining hard}}.","Está chovendo forte."),("Take your galoshes.","Leve suas galochas."),("The wipers are on.","Os limpadores estão ligados.")],"O que significa raining cats and dogs?",["chuva forte","gatos caindo","chuva fraca"],0,"Chuva forte."),
80333:("Adjetivos de tamanho","Tamanho: **big, small, huge, tiny.** *A tiny crab. A huge whale.* Adjetivo antes do nome.",[("A {{tiny}} crab.","Um caranguejo minúsculo."),("A {{huge}} whale.","Uma baleia enorme."),("A {{big}} jellyfish.","Uma água-viva grande."),("A small starfish.","Uma estrela-do-mar pequena.")],"Oposto de huge:",["tiny","big","long"],0,"Tiny."),
80334:("Can / can't","Trilha: **I can see the peak. I can't hear anything.** **Can** + verbo base. *Silence* = silêncio.",[("I {{can see}} the peak.","Consigo ver o pico."),("I {{can't hear}} anything.","Não ouço nada."),("We {{can walk}} to the lake.","Podemos ir até o lago."),("Take your boots.","Leve suas botas.")],"“Não consigo ver”:",["I can't see.","I no can see.","I don't can see."],0,"can't."),
80335:("Cuidar de plantas","Plantas: **Water the flowers. Plant the seeds. Put them in the pot.** Imperativo para instruções.",[("{{Water}} the flowers.","Regue as flores."),("{{Plant}} the seeds.","Plante as sementes."),("{{Put}} them in the pot.","Coloque-os no vaso."),("The soil is wet.","A terra está úmida.")],"“Regue as flores”:",["Water the flowers.","You water flowers.","Watering flowers."],0,"Imperativo."),
80336:("Have, has","Pets: **I have a dog. She has a cat.** **Has** com he/she/it. *Do you have a pet?*",[("I {{have}} a dog."," Tenho um cachorro."),("She {{has}} a cat.","Ela tem um gato."),("Do you {{have}} a pet?","Você tem um bicho de estimação?"),("The vet is kind.","O veterinário é gentil.")],"Complete: “He ___ a leash.”",["have","has","haves"],1,"has."),
80337:("Aniversário","Datas: **My birthday is on May 5th.** Ordinais: **first, second, third.** *Happy birthday!* **On** + data.",[("My birthday is {{on}} May 5th.","Meu aniversário é em 5 de maio."),("It's my {{fifth}} birthday.","É meu quinto aniversário."),("Blow out the candles!","Sopre as velas!"),("Happy birthday!","Feliz aniversário!")],"“Aniversário no dia 2”:",["on the second","in the second","at second"],0,"on + data."),
}
